package initialtest

import (
	"emon/initial"
	"emon/port"
	"testing"
)

func itPut(c *port.Cells, b []byte) int32 {
	// The ASCII text of b as code points appended to c; answers where they start.
	var start int32 = port.BlobLen(b)
	var i int32 = 0
	for i < start {
		port.CellsPush(c, port.BlobU8(b, i))
		i += 1
	}
	return 0
}

func itJoin(loc *port.Cells, cp int32, word []byte) int32 {
	// `in-join` for an initial of the one code point cp before `word`.
	var et *port.Cells = port.NewCells()
	itPut(et, word)
	return initial.InJoin(loc, cp, et, 0, port.BlobLen(word))
}

func itLang(tag []byte) int32 {
	var loc *port.Cells = port.NewCells()
	itPut(loc, tag)
	return initial.InLang(loc)
}

func TestALocaleTagNamesALanguage(emonT *testing.T) {
	port.AssertEq(emonT, itLang(port.TextBlob("")), 0, "no tag")
	port.AssertEq(emonT, itLang(port.TextBlob("e")), 0, "one letter is no tag")
	port.AssertEq(emonT, itLang(port.TextBlob("en")), 1, "en")
	port.AssertEq(emonT, itLang(port.TextBlob("EN-us")), 1, "case does not matter, a region follows")
	port.AssertEq(emonT, itLang(port.TextBlob("en_GB")), 1, "an underscore too")
	port.AssertEq(emonT, itLang(port.TextBlob("de-CH")), 2, "de")
	port.AssertEq(emonT, itLang(port.TextBlob("fr")), 3, "fr")
	port.AssertEq(emonT, itLang(port.TextBlob("es-419")), 4, "es")
	port.AssertEq(emonT, itLang(port.TextBlob("pt-BR")), 5, "pt")
	port.AssertEq(emonT, itLang(port.TextBlob("it")), 6, "it")
	port.AssertEq(emonT, itLang(port.TextBlob("nl-BE")), 7, "nl")
	port.AssertEq(emonT, itLang(port.TextBlob("zh-Hans")), 99, "a language without a table")
	port.AssertEq(emonT, itLang(port.TextBlob("english")), 99, "a word is not a tag")
}

func TestTheJoinWithoutALocale(emonT *testing.T) {
	var none *port.Cells = port.NewCells()
	port.AssertEq(emonT, itJoin(none, 65, port.TextBlob("long")), 1, "`A` + `long`: joined, flagged (the union of the tables has `A`)")
	port.AssertEq(emonT, itJoin(none, 73, port.TextBlob("t")), 1, "`I` + `t`: flagged too")
	port.AssertEq(emonT, itJoin(none, 69, port.TextBlob("verything")), 1, "`E` is a word in Spanish, Italian, Portuguese")
	port.AssertEq(emonT, itJoin(none, 84, port.TextBlob("he")), 0, "`T` + `he`: no language has a word `T`")
	port.AssertEq(emonT, itJoin(none, 81, port.TextBlob("uiet")), 0, "`Q` + `uiet`")
	port.AssertEq(emonT, itJoin(none, 65, port.TextBlob("")), 1, "no word after it: still flagged")
}

func TestTheJoinWithALocale(emonT *testing.T) {
	var en *port.Cells = port.NewCells()
	var de *port.Cells = port.NewCells()
	var fr *port.Cells = port.NewCells()
	var zh *port.Cells = port.NewCells()
	itPut(en, port.TextBlob("en-US"))
	itPut(de, port.TextBlob("de"))
	itPut(fr, port.TextBlob("fr"))
	itPut(zh, port.TextBlob("zh"))
	// English lists: the words a one-letter word is followed by, and the rest of a word the letter begins.
	port.AssertEq(emonT, itJoin(en, 65, port.TextBlob("long")), 2, "`A` + `long`: a space, the letter is a word")
	port.AssertEq(emonT, itJoin(en, 73, port.TextBlob("was")), 2, "`I` + `was`")
	port.AssertEq(emonT, itJoin(en, 73, port.TextBlob("t")), 0, "`I` + `t`: `It`, sure")
	port.AssertEq(emonT, itJoin(en, 65, port.TextBlob("t")), 0, "`A` + `t`: `At`")
	port.AssertEq(emonT, itJoin(en, 79, port.TextBlob("nce")), 0, "`O` + `nce`: `Once`")
	port.AssertEq(emonT, itJoin(en, 65, port.TextBlob("xyzzy")), 1, "a word neither list knows: joined, flagged")
	port.AssertEq(emonT, itJoin(en, 84, port.TextBlob("he")), 0, "`T` is no word")
	port.AssertEq(emonT, itJoin(en, 97, port.TextBlob("long")), 2, "a lower-case letter is read as its capital")
	// A language with a one-letter table and no list joins and flags; one without the letter joins.
	port.AssertEq(emonT, itJoin(de, 79, port.TextBlob("ma")), 1, "German `O`")
	port.AssertEq(emonT, itJoin(de, 65, port.TextBlob("long")), 0, "German has no one-letter `A`")
	port.AssertEq(emonT, itJoin(fr, 192, port.TextBlob("propos")), 1, "French `À`")
	port.AssertEq(emonT, itJoin(zh, 65, port.TextBlob("long")), 1, "a language without a table: the union")
}
